/* eslint-disable @typescript-eslint/no-unused-vars -- port of the team's closure: dead locals and shapes stay as delivered */
// Literal port of the team's Casa3DSDK (module house/floors). Generated by codemod and reviewed; see MIGRATION.md.
import { PLASTER_PER_FACE } from '@adatechnology/game-floorplan-structure';
import type { Outbuilding, StructurePart } from '@adatechnology/game-floorplan-structure';

import type { Flight, HouseRecord, HouseRoom, Kernel, KernelHouseFloors, PieceRecord, Rect, Shared, Tile } from '../kernel-types.js';
import { outsideBoxes } from './solids.js';
import type { Aabb } from './solids.js';

/** How far the ground floor's finish stands over the ground in the construction stages, metres. */
export const FLOOR_OVER_GROUND = 0.012;
/** How deep the ground floor's finish goes, built by construction stage: down to the lot's base (3 cm under the ground), never into it. */
export const FLOOR_UNDER_GROUND = 0.03;

/** The render and paint under a ceiling slab, metres; the rest of the slab is concrete. */
const CEILING_PAINT = 0.015
/** Bare concrete of a slab's top. */
const SLAB_CONCRETE = 0x8f8e8a
/** How far the outer face of a 15 cm wall stands past the edge of its room, metres. */
const WALL_FACE = 0.075

export function installHouseFloors(K: Kernel, shared: Shared): void {
  const { rectsOf, EPS, OPEN_AREA, Y0, bx, cursor, floorColor, stairFootprint, structurePiece, subRects } = K;
  /**
   * The outbuilding's roof slab past its room: over its walls out to their outer faces (it bears on them, nothing of the wall shows above it), its edge rendered
   * with the facade's finish, flush with the wall's face under it.
   */
  function outbuildingSlabEdge(room: HouseRecord['rooms'][number], y0: number, slab: string | null | undefined): void {
    const R: HouseRecord = shared.ctx.r;
    const e = (R.outbuildings ?? []).find((o) => o.id === room.id);
    if (!e) return;
    const half = (e.thickness ?? 0.15) / 2;
    const outer: [number, number, number, number] = [e.aabb[0] - half, e.aabb[1] - half, e.aabb[2] + half, e.aabb[3] + half];
    const yb = y0 + room.ceiling, yt = yb + 0.2;
    const face = K.sideOf('outside', false);
    const inner: [number, number, number, number] = [outer[0] + PLASTER_PER_FACE, outer[1] + PLASTER_PER_FACE, outer[2] - PLASTER_PER_FACE, outer[3] - PLASTER_PER_FACE];
    cursor.pc = slab ? structurePiece(slab) : null;
    // the concrete over the walls, round the room's ceiling
    // (round what the room's ceiling already covers: the two never fill the same space)
    const covered = coveredRects(room);
    for (const r of subRects([inner], covered)) { bx('plain', r[0], yb, r[1], r[2], yt, r[3], SLAB_CONCRETE); shared.ctx.occupied.push([r[0], yb, r[1], r[2], yt, r[3]]); }
    // its edge's render: a band of the facade's finish on each side, from the wall's top to the slab's
    for (const r of subRects(subRects([outer], [inner]), covered)) { bx(face.mat, r[0], yb, r[1], r[2], yt, r[3], face.color); shared.ctx.occupied.push([r[0], yb, r[1], r[2], yt, r[3]]); }
  }
  function flights(): Flight[] { // each flight between floors only once (the SDK repeats the item at departure and arrival)
    if (shared.ctx._flights && shared.ctx._flights.r === shared.ctx.r) return shared.ctx._flights.l;
    const R: HouseRecord = shared.ctx.r, mp = new Map<string, Flight>();
    for (const m of R.items) { if (m.type !== 'stairs' || !m.link || typeof m.link !== 'object') continue; const k = [m.link.from, m.link.to, m.x.toFixed(2), m.z.toFixed(2), (m.ry || 0).toFixed(2)].join('|'); if (!mp.has(k)) mp.set(k, { m, from: m.link.from, to: m.link.to, rect: stairFootprint(m) }); }
    const l = [...mp.values()], inter = (a: Rect, b: Rect): boolean => a[0] < b[2] - EPS && a[2] > b[0] + EPS && a[1] < b[3] - EPS && a[3] > b[1] + EPS;
    for (const v of l) if (l.some(o => o !== v && o.to === v.from && inter(o.rect, v.rect))) { // stacked flight: landing under the first steps (headroom for the flight below)
      const m = v.m, H = Y0(v.to) - Y0(v.from), len = Math.min(m.d * 0.5, Math.max(0.7, m.d * (H - 0.24 - 1.95) / H)), c = Math.cos(m.ry), s_ = Math.sin(m.ry), lz = m.d / 2 - len / 2;
      v.landing = stairFootprint({ x: m.x + lz * s_, z: m.z + lz * c, ry: m.ry, w: m.w, d: len });
    }
    for (const v of l) if (!l.some(o => o !== v && o.from === v.to && inter(o.rect, v.rect))) { // top of a flight with no other flight above: landing (flat floor of the arrival floor) in the last 0.9 m
      const m = v.m, LP = Math.min(0.9, m.d * 0.28), lz = -m.d / 2 + LP / 2; v.LP = LP;
      v.top = stairFootprint({ x: m.x + lz * Math.sin(m.ry), z: m.z + lz * Math.cos(m.ry), ry: m.ry, w: m.w, d: LP });
    }
    shared.ctx._flights = { r: R, l }; return l;
  }
  // The slab pieces of the plan are cut into panels by the structure (`slabPanelView`): a tile of a floor, an underside or a ceiling is split at the borders of
  // the panels and each part is tagged with its own panel, so the panel that fails drops alone. A slab with no panels (a plan with plain slabs) stays one piece.
  const panelRects = (p: StructurePart): Rect[] => (p.footprint && p.footprint.length ? p.footprint : [p.aabb]);
  function tilesOf(parent: string | null | undefined, rc: Rect): Tile[] {
    const ps: StructurePart[] | undefined = parent ? shared.ctx.panelsOf && shared.ctx.panelsOf.get(parent) : undefined;
    if (!ps) return [[parent ? structurePiece(parent) : null, rc]];
    const out: Tile[] = [], taken: Rect[] = [];
    for (const p of ps) for (const q of panelRects(p)) {
      const r: Rect = [Math.max(rc[0], q[0]), Math.max(rc[1], q[1]), Math.min(rc[2], q[2]), Math.min(rc[3], q[3])];
      if (r[2] - r[0] > EPS && r[3] - r[1] > EPS) { out.push([structurePiece(p.id), r]); taken.push(r); }
    }
    for (const r of subRects([rc], taken)) out.push([null, r]);
    return out;
  }
  function panelAt(parent: string, x: number, z: number): PieceRecord | null {
    const ps: StructurePart[] | undefined = shared.ctx.panelsOf && shared.ctx.panelsOf.get(parent);
    if (!ps) return structurePiece(parent);
    for (const p of ps) for (const q of panelRects(p)) if (x >= q[0] - EPS && x <= q[2] + EPS && z >= q[1] - EPS && z <= q[3] + EPS) return structurePiece(p.id);
    return null;
  }
  const hasSlab = (id: string): boolean => !!(shared.ctx.structureIndex[id] || (shared.ctx.panelsOf && shared.ctx.panelsOf.has(id)));
  function floorsAndSlabs() {
    const R: HouseRecord = shared.ctx.r, nA = R.floors.length, C = shared.ctx.colors;
    const V = flights(), holes = (f: number): readonly Rect[] => V.filter(v => v.to === f).flatMap(v => { let rs: readonly Rect[] = [v.rect]; if (v.top) rs = subRects(rs, [v.top]); for (const o of V) if (o.from === f && o.landing) rs = subRects(rs, [o.landing]); return rs; }), landings = (f: number): (Rect | undefined)[] => V.filter(v => v.from === f && v.landing).map(v => v.landing);
    for (let f = 0; f < nA; f++) {
      cursor.group = 'f' + f; const y0 = Y0(f), bur = holes(f);
      for (const c of R.rooms.filter(c => c.floor === f)) {
        if (c.type === 'void' || c.outbuilding || (c.type === 'elevator' && f > 0)) continue;
        const col = floorColor(c), parent = f > 0 ? ['slab_' + f + '_' + c.type, 'slab_' + f + '_' + c.id, 'slab_' + f].find(hasSlab) : null;
        // built by construction stage, the ground floor's finish stands 1.2 cm over the ground the house sits on, never on its plane
        const lift = shared.ctx.constructionStages && f === 0 ? FLOOR_OVER_GROUND : 0;
        const under = shared.ctx.constructionStages && f === 0 && !shared.ctx.visorScene ? FLOOR_UNDER_GROUND : 0.04;
        for (const rc of subRects(rectsOf(c), bur)) for (const [pc, r] of tilesOf(parent, rc)) {
          cursor.pc = pc;
          // an upper storey's finish keeps round the walls of the storey under it (they stand up to its top): no end of one on a wall's end
          const tile: Aabb = [r[0], y0 - under, r[1], r[2], y0 + lift, r[3]];
          for (const b of f > 0 && !shared.ctx.visorScene ? outsideBoxes(tile, shared.ctx.occupied) : [tile]) { bx('plaster', b[0], b[1], b[2], b[3], b[4], b[5], col); if (!shared.ctx.visorScene) shared.ctx.floorFinishes.push(b); }
        }
      }
      if (f > 0) { // slab under the floor
        const rs = R.rooms.filter(c => c.floor === f && c.type !== 'void' && c.type !== 'elevator').flatMap(rectsOf); 
        for (const rc of subRects(rs, bur)) for (const [pc, r] of tilesOf('slab_' + f, rc)) { cursor.pc = pc; for (const b of shared.ctx.visorScene ? [[r[0], y0 - 0.24, r[1], r[2], y0 - 0.04, r[3]] as const] : outsideBoxes([r[0], y0 - 0.24, r[1], r[2], y0 - 0.04, r[3]], shared.ctx.occupied)) { bx('plaster', b[0], b[1], b[2], b[3], b[4], b[5], C.ceiling != null ? C.ceiling : 0xeeeae2); if (!shared.ctx.visorScene) shared.ctx.floorFinishes.push(b); } }
      }
      // ceiling of the rooms with nothing above
      cursor.group = 't' + f; const ceilingOf = hasSlab('slab_' + (f + 1)) ? 'slab_' + (f + 1) : (f === nA - 1 ? ['slab_ceiling', 'slab_top'].find(hasSlab) : null);
      const above = R.rooms.filter(c => c.floor === f + 1).flatMap(rectsOf);
      const edges = slabEdgeStrips(f, above);
      for (const c of R.rooms.filter(c => c.floor === f && !OPEN_AREA(c))) for (const rc of subRects(coveredRects(c), above)) for (const [pc, tile] of tilesOf(ceilingOf, rc)) {
        // the slab is concrete, bare on top under the roof; only its underside is rendered and painted (the room's ceiling)
        cursor.pc = pc;
        if (shared.ctx.visorCeilings) { bx('plaster', tile[0], y0 + c.ceiling, tile[1], tile[2], y0 + c.ceiling + 0.2, tile[3], C.ceiling != null ? C.ceiling : 0xeeeae2); continue; }
        // the strips of its edge that face the outside are rendered like the walls: nothing of the tile stands in them
        // (and round the walls standing through it: a storey's walls over a double-height room, a wall higher than the ceiling)
        for (const r of subRects([tile], edges)) for (const b of outsideBoxes([r[0], y0 + c.ceiling, r[1], r[2], y0 + c.ceiling + 0.2, r[3]], shared.ctx.occupied)) {
          bx('plaster', b[0], b[1], b[2], b[3], Math.min(b[4], y0 + c.ceiling + CEILING_PAINT), b[5], C.ceiling != null ? C.ceiling : 0xeeeae2); bx('plain', b[0], Math.max(b[1], y0 + c.ceiling + CEILING_PAINT), b[2], b[3], b[4], b[5], SLAB_CONCRETE); shared.ctx.occupied.push(b);
        }
      }
      if (edges.length) {
        const face = K.sideOf('outside', false), yb = y0 + (R.rooms.find(c => c.floor === f && !c.outbuilding)?.ceiling ?? 0);
        cursor.pc = ceilingOf ? structurePiece(ceilingOf) : null;
        for (const r of edges) for (const b of outsideBoxes([r[0], yb, r[1], r[2], yb + 0.2, r[3]], shared.ctx.occupied)) { bx(face.mat, b[0], b[1], b[2], b[3], b[4], b[5], face.color); shared.ctx.occupied.push(b); }
      }
      if (!shared.ctx.visorCeilings) for (const c of R.rooms.filter((x) => x.floor === f && x.outbuilding)) outbuildingSlabEdge(c, y0, ceilingOf);
      cursor.pc = null;
      cursor.pc = null;
    }
  }
  /**
   * The strips of the slab's edge that face the outside, from the wall's outer face in by the depth of its render: the slab is cast against the bond beam, so its
   * edge is rendered and painted like the wall under it, never bare concrete. Only when drawn by construction stage (otherwise the eave band covers it).
   */
  function slabEdgeStrips(floor: number, above: readonly Rect[]): readonly Rect[] {
    if (!shared.ctx.constructionStages || shared.ctx.visorCeilings) return [];
    const rooms = (shared.ctx.r as HouseRecord).rooms.filter((c) => c.floor === floor && !OPEN_AREA(c) && !c.outbuilding);
    const grown = (by: number): Rect[] => rooms.flatMap((c) => rectsOf(c).map((r): Rect => [r[0] - by, r[1] - by, r[2] + by, r[3] + by]));
    return subRects(subRects(grown(WALL_FACE), above), grown(WALL_FACE - PLASTER_PER_FACE));
  }
  // built by construction stage, the slab over the top rooms is seen from above before the roof goes on: it covers the walls round them too (to the outer faces
  // of an outbuilding's walls), so no groove runs along each wall top
  function coveredRects(c: HouseRoom): readonly Rect[] {
    if (!shared.ctx.constructionStages) return rectsOf(c);
    const e = c.outbuilding ? ((shared.ctx.outbuildingList || []) as Outbuilding[]).find((o) => o.id === c.id) : undefined;
    if (e) { const h = (e.thickness || 0.15) / 2 - 0.005; return [[e.aabb[0] - h, e.aabb[1] - h, e.aabb[2] + h, e.aabb[3] + h]]; }
    const h = 0.07; return rectsOf(c).map((r) => [r[0] - h, r[1] - h, r[2] + h, r[3] + h]); // to 5 mm inside the walls' outer faces: never on the eave band's plane
  }
  Object.assign(K, { flights, floorsAndSlabs, tilesOf, panelAt });
}
